/**
 * Real AFL per-season statistics, sourced from afltables.com player pages, scraped league-wide
 * via the AFL Tables Apps Script (round 74+, Tyler's own "AFL 2026 Players DB" workbook,
 * 'AFL Tables Career Totals' tab, scraped 2026-09-05). Backfills PlayerProfileModal's "Career
 * & Season Stats" table with genuine year-by-year history for real players, instead of that
 * table starting blank at whatever year this save happened to begin.
 *
 * SCOPE, HONESTLY, ROUND 74 (superseding round 67's NMFC-only version): every real player in
 * the sheet's 668 active-2026-list rows whose name matched this save's own
 * `Player.realFullName` exactly — 583 players, 3939 player-seasons. The remaining
 * 85 sheet names (nicknames, or a name-format mismatch against this app's own real-name
 * strings — e.g. "Paddy" vs the sheet's formal first name, or the reverse) did not match and are
 * NOT included here rather than guessed at; realSeasonHistoryFor simply returns [] for them and
 * for any real player the sheet's scraper itself never reached, the same "silently absent, not
 * faked" convention realDraftHistory.ts already established. See this file's own generator
 * (scripts/genSeasonHistory notes in ROADMAP.md round 74) for the excluded-name list if the gap
 * ever needs closing by hand.
 *
 * FIELD COVERAGE, HONESTLY: unchanged from round 67 — afltables' classic per-season "Year" table
 * doesn't carry 5 of this app's 22 tracked LeagueStat categories (markLeadWins, hitoutsToAdvantage,
 * spoils, interceptMarks, interceptPossessions, turnovers — all newer, manually-charted advanced
 * stats with no classic-era equivalent; real rows report 0, not fabricated). shotsAtGoal is still
 * derived as goals+behinds. Every other field (kicks, handballs, disposals, marks, marksInside50,
 * clearances, tackles, hitouts, frees for/against, contested/uncontested possessions, goals,
 * behinds, goalAssists) is a genuine afltables column. The source sheet also carries a team
 * W-D-L record, jumper number, Brownlow votes, rebound 50s, inside 50s, contested marks, one
 * percenters and bounces per season — none of that is carried into this file, matching round 67's
 * own precedent of only importing fields this app's own LeagueStat set already tracks. (The W-D-L
 * column is additionally unreliable in the source workbook — Excel silently reinterpreted a chunk
 * of "W-D-L" text cells as dates during the original scrape/paste, e.g. Pendlebury's 2020 row —
 * one more reason it was left out rather than trusted.)
 *
 * Rows are stored for every year afltables has (including a player's real 2026 row) — the year
 * < CURRENT_SEASON_YEAR cutoff that keeps real and this-save-simulated seasons from double-
 * counting lives in the merge logic (PlayerProfileModal.tsx's combinedYearRowsFor), not here.
 *
 * Deliberately NOT folded into engine/seasonSummary.ts's allTimePlayerTotals — see round 67's
 * doc comment (unchanged reasoning): this file's merge is scoped to exactly one place, the Player
 * Profile's own Career & Season Stats display.
 */

export interface RealSeasonEntry {
  player: string;
  year: number;
  team: string;
  games: number;
  kicks: number;
  handballs: number;
  disposals: number;
  marks: number;
  marksInside50: number;
  clearances: number;
  tackles: number;
  hitouts: number;
  freeKicksFor: number;
  freeKicksAgainst: number;
  contestedPoss: number;
  uncontestedPoss: number;
  goals: number;
  behinds: number;
  goalAssists: number;
}

// Compact tuple form (matches realDraftHistory.ts's established convention) — mapped to
// RealSeasonEntry below. Order: [year, team, games, kicks, handballs, marks, marksInside50,
// clearances, tackles, hitouts, freeKicksFor, freeKicksAgainst, contestedPoss, uncontestedPoss,
// goals, behinds, goalAssists].
type RawRow = [number, string, number, number, number, number, number, number, number, number, number, number, number, number, number, number, number];

function toEntry(player: string, r: RawRow): RealSeasonEntry {
  return {
    player,
    year: r[0],
    team: r[1],
    games: r[2],
    kicks: r[3],
    handballs: r[4],
    disposals: r[3] + r[4],
    marks: r[5],
    marksInside50: r[6],
    clearances: r[7],
    tackles: r[8],
    hitouts: r[9],
    freeKicksFor: r[10],
    freeKicksAgainst: r[11],
    contestedPoss: r[12],
    uncontestedPoss: r[13],
    goals: r[14],
    behinds: r[15],
    goalAssists: r[16],
  };
}

