export const REAL_SEASON_HISTORY: RealSeasonEntry[] = Object.entries(RAW).flatMap(([player, rows]) =>
  rows.map((r) => toEntry(player, r)),
);

/** Every real season on record for this player, oldest first — `[]` if the real-world scrape
 * never covered them (see this file's own doc comment for exact coverage/exclusions). Pass
 * `Player.realFullName`, NOT the live display name — see `Player.realFullName`'s own doc comment
 * for why. */
export function realSeasonHistoryFor(fullName: string): RealSeasonEntry[] {
  return REAL_SEASON_HISTORY.filter((e) => e.player === fullName).sort((a, b) => a.year - b.year);
}
